from datetime import date, timedelta


class Library:
    def __init__(self, loan_days: int = 14, daily_fine: float = 0.5) -> None:
        self.loan_days = loan_days
        self.daily_fine = daily_fine
        self._books: set[str] = set()
        self._loans: dict[str, tuple[str, date]] = {}
        self._user_books: dict[str, str] = {}
        self._fines: dict[str, float] = {}

    def add_book(self, book_id: str) -> None:
        self._books.add(book_id)

    def borrow(self, user: str, book_id: str, day: date) -> None:
        if book_id not in self._books:
            raise ValueError("Book is not in the library")
        if book_id in self._loans:
            raise ValueError("Book is already borrowed")
        if user in self._user_books:
            raise ValueError("User already holds a book")

        self._loans[book_id] = (user, day)
        self._user_books[user] = book_id

    def return_book(self, user: str, book_id: str, day: date) -> float:
        loan = self._loans.get(book_id)
        if loan is None or loan[0] != user:
            raise ValueError("User has not borrowed this book")

        due_date = loan[1] + timedelta(days=self.loan_days)
        delay = max(0, (day - due_date).days)
        weeks, remaining_days = divmod(delay, 7)
        weekdays = weeks * 5
        for offset in range(1, remaining_days + 1):
            if (due_date.weekday() + offset) % 7 < 5:
                weekdays += 1

        fine = weekdays * self.daily_fine
        self._fines[user] = self._fines.get(user, 0.0) + fine
        del self._loans[book_id]
        del self._user_books[user]
        return fine

    def unpaid_fines(self, user: str) -> float:
        return self._fines.get(user, 0.0)

    def pay(self, user: str) -> None:
        self._fines.pop(user, None)
